import type { ContentPack } from '../types';
import { glesson as G, lesson, M, mix, Nq, TF } from '../lib';
import { coulomb, efficiency, electricPower, gasLaws, heat, massConservation, motionGraph, ohm, seriesParallel, siUnits } from '../gensSci';
import { absRelError } from '../gensEso';

const P: ContentPack = {
  '3E-FQ-1': lesson(['La física y la química avanzan gracias a muchas personas: Galileo (método experimental), Lavoisier (conservación de la masa), Faraday (electromagnetismo), Marie Curie (radiactividad), Dorothy Hodgkin (estructura de moléculas con rayos X).|La física i la química avancen gràcies a moltes persones: Galileu (mètode experimental), Lavoisier (conservació de la massa), Faraday (electromagnetisme), Marie Curie (radioactivitat), Dorothy Hodgkin (estructura de molècules amb raigs X).|Physics and chemistry advance thanks to many people: Galileo (experimental method), Lavoisier (conservation of mass), Faraday (electromagnetism), Marie Curie (radioactivity), Dorothy Hodgkin (structure of molecules using X-rays).'],
    '¿Quién es considerado padre de la química moderna?|Qui és considerat pare de la química moderna?|Who is considered the father of modern chemistry?', ['Midió con precisión la masa en las reacciones.|Va mesurar amb precisió la massa en les reaccions.|He measured mass carefully in reactions.', 'Antoine Lavoisier.|Antoine Lavoisier.|Antoine Lavoisier.'], [
      M('¿Quién descubrió la inducción electromagnética?|Qui va descobrir la inducció electromagnètica?|Who discovered electromagnetic induction?', 'Michael Faraday|Michael Faraday|Michael Faraday', ['Isaac Newton|Isaac Newton|Isaac Newton', 'Charles Darwin|Charles Darwin|Charles Darwin'], 'Base de los generadores eléctricos.|Base dels generadors elèctrics.|The basis of electric generators.'),
      M('Dorothy Hodgkin ganó el Nobel de Química por…|Dorothy Hodgkin va guanyar el Nobel de Química per…|Dorothy Hodgkin won the Nobel Prize in Chemistry for…', 'determinar estructuras de moléculas con rayos X|determinar estructures de molècules amb raigs X|working out molecular structures with X-rays', ['inventar la bombilla|inventar la bombeta|inventing the light bulb', 'descubrir América|descobrir Amèrica|discovering America'], 'Como la penicilina o la insulina.|Com la penicil·lina o la insulina.|Such as penicillin and insulin.'),
      M('Galileo defendió que la ciencia debe basarse en…|Galileu va defendre que la ciència s’ha de basar en…|Galileo argued that science should be based on…', 'experimentos y medidas|experiments i mesures|experiments and measurements', ['opiniones de autoridades|opinions d’autoritats|the opinions of authorities', 'la suerte|la sort|luck'], 'Método experimental.|Mètode experimental.|The experimental method.'),
      M('James Chadwick descubrió…|James Chadwick va descobrir…|James Chadwick discovered…', 'el neutrón|el neutró|the neutron', ['el electrón|l’electró|the electron', 'el oxígeno|l’oxigen|oxygen'], 'En 1932.|El 1932.|In 1932.'),
      TF('Las mujeres científicas han hecho aportaciones clave aunque a menudo no se reconocieron.|Les dones científiques han fet aportacions clau encara que sovint no es van reconéixer.|Women scientists have made key contributions, though often unrecognised.', true, 'Rosalind Franklin, Lise Meitner…|Rosalind Franklin, Lise Meitner…|Rosalind Franklin, Lise Meitner…'),
      M('¿Quién estudió la relación entre presión y volumen de un gas?|Qui va estudiar la relació entre pressió i volum d’un gas?|Who studied the link between gas pressure and volume?', 'Robert Boyle|Robert Boyle|Robert Boyle', ['Gregor Mendel|Gregor Mendel|Gregor Mendel', 'Alfred Wegener|Alfred Wegener|Alfred Wegener'], 'Ley de Boyle.|Llei de Boyle.|Boyle’s law.'),
    ]),
  '3E-FQ-2': G(['Toda medida tiene una incertidumbre. La precisión depende del instrumento (su sensibilidad). Se dan los resultados con unidades y cifras significativas razonables. Las gráficas muestran la relación entre variables.|Tota mesura té una incertesa. La precisió depén de l’instrument (la seua sensibilitat). Es donen els resultats amb unitats i xifres significatives raonables. Les gràfiques mostren la relació entre variables.|Every measurement has an uncertainty. Precision depends on the instrument (its resolution). Results are given with units and sensible significant figures. Graphs show how variables are related.'],
    'Una regla mide de milímetro en milímetro. ¿Sensibilidad?|Un regle mesura de mil·límetre en mil·límetre. Sensibilitat?|A ruler measures in millimetres. Resolution?', ['La división más pequeña.|La divisió més xicoteta.|The smallest division.', '1 mm.|1 mm.|1 mm.'], mix(absRelError(), motionGraph(), siUnits())),
  '3E-FQ-3': lesson(['Un proyecto de investigación sigue el método científico: pregunta, hipótesis, diseño experimental con variables controladas, toma de datos, análisis con tablas y gráficas, conclusiones y comunicación.|Un projecte d’investigació seguix el mètode científic: pregunta, hipòtesi, disseny experimental amb variables controlades, presa de dades, anàlisi amb taules i gràfiques, conclusions i comunicació.|A research project follows the scientific method: question, hypothesis, experimental design with controlled variables, data collection, analysis with tables and graphs, conclusions and communication.'],
    '¿Influye la altura desde la que cae una pelota en lo que bota?|Influïx l’altura des de la qual cau una pilota en el que bota?|Does the drop height of a ball affect how high it bounces?', ['Independiente: altura de caída. Dependiente: altura del bote.|Independent: altura de caiguda. Dependent: altura del bot.|Independent: drop height. Dependent: bounce height.', 'Misma pelota y mismo suelo; repetir varias veces.|Mateixa pilota i mateix sòl; repetir diverses vegades.|Same ball and floor; repeat several times.'], [
      M('¿Por qué se repite varias veces una medida?|Per què es repetix diverses vegades una mesura?|Why repeat a measurement several times?', 'para reducir el error y calcular la media|per a reduir l’error i calcular la mitjana|to reduce error and find an average', ['para tardar más|per a tardar més|to take longer', 'para cambiar la hipótesis|per a canviar la hipòtesi|to change the hypothesis'], 'Los errores aleatorios se compensan.|Els errors aleatoris es compensen.|Random errors cancel out.'),
      M('¿Qué es una variable controlada?|Què és una variable controlada?|What is a control variable?', 'la que se mantiene igual en todas las pruebas|la que es manté igual en totes les proves|one kept the same in every trial', ['la que cambias|la que canvies|the one you change', 'la que mides|la que mesures|the one you measure'], 'Así la comparación es justa.|Així la comparació és justa.|That keeps the test fair.'),
      TF('Una conclusión debe basarse en los datos, aunque contradiga la hipótesis.|Una conclusió s’ha de basar en les dades, encara que contradiga la hipòtesi.|A conclusion must be based on the data, even if it contradicts the hypothesis.', true, 'La hipótesis se acepta o se rechaza.|La hipòtesi s’accepta o es rebutja.|The hypothesis is accepted or rejected.'),
      M('Un dato muy distinto de los demás (anómalo) debe…|Una dada molt diferent de les altres (anòmala) ha de…|A result very different from the others (an outlier) should be…', 'revisarse y repetir la medida|revisar-se i repetir la mesura|checked and the measurement repeated', ['borrarse sin decir nada|esborrar-se sense dir res|deleted without saying so', 'copiarse dos veces|copiar-se dues vegades|copied twice'], 'Puede haber un error.|Hi pot haver un error.|There may be a mistake.'),
      M('¿Dónde se comunican los resultados en ciencia?|On es comuniquen els resultats en ciència?|Where are scientific results shared?', 'en informes y revistas revisadas por expertos|en informes i revistes revisades per experts|in reports and peer-reviewed journals', ['solo en redes sociales|només en xarxes socials|only on social media', 'en ningún sitio|en cap lloc|nowhere'], 'Otros científicos los comprueban.|Altres científics els comproven.|Other scientists check them.'),
      TF('En un informe se deben citar las fuentes consultadas.|En un informe s’han de citar les fonts consultades.|A report should cite the sources used.', true, 'Es honesto y permite comprobarlo.|És honest i permet comprovar-ho.|It is honest and lets others check.'),
    ]),
  '3E-FQ-4': lesson(['Modelo cinético de los gases: las partículas están muy separadas, se mueven al azar a gran velocidad y chocan contra las paredes del recipiente; esos choques producen la presión. A más temperatura, más rápido se mueven.|Model cinètic dels gasos: les partícules estan molt separades, es mouen a l’atzar a gran velocitat i xoquen contra les parets del recipient; eixos xocs produïxen la pressió. A més temperatura, més ràpid es mouen.|Kinetic model of gases: particles are far apart, move randomly at high speed and hit the container walls; those collisions cause pressure. The higher the temperature, the faster they move.'],
    '¿Por qué un balón se hincha más al sol?|Per què un baló s’infla més al sol?|Why does a ball inflate more in the sun?', ['Las partículas del aire se mueven más deprisa.|Les partícules de l’aire es mouen més de pressa.|The air particles move faster.', 'Chocan más fuerte: sube la presión.|Xoquen més fort: puja la pressió.|They hit harder: pressure rises.'], [
      M('La presión de un gas se debe a…|La pressió d’un gas es deu a…|Gas pressure is caused by…', 'los choques de las partículas con las paredes|els xocs de les partícules amb les parets|particles hitting the walls', ['el peso del recipiente|el pes del recipient|the weight of the container', 'el color del gas|el color del gas|the colour of the gas'], 'Cada choque empuja un poco.|Cada xoc empeny una mica.|Each collision pushes a little.'),
      TF('A 0 K (cero absoluto) las partículas tendrían la mínima energía posible.|A 0 K (zero absolut) les partícules tindrien la mínima energia possible.|At 0 K (absolute zero) particles would have the least possible energy.', true, '0 K = −273 °C.|0 K = −273 °C.|0 K = −273 °C.'),
      M('Si comprimo un gas en una jeringa tapada…|Si comprimisc un gas en una xeringa tapada…|If I compress a gas in a sealed syringe…', 'aumenta la presión|augmenta la pressió|the pressure rises', ['disminuye la presión|disminuïx la pressió|the pressure falls', 'desaparecen partículas|desapareixen partícules|particles vanish'], 'Más choques por segundo.|Més xocs per segon.|More collisions per second.'),
      TF('Los gases se pueden comprimir porque hay mucho espacio vacío entre partículas.|Els gasos es poden comprimir perquè hi ha molt d’espai buit entre partícules.|Gases can be compressed because there is lots of empty space between particles.', true, 'Las partículas se acercan.|Les partícules s’acosten.|The particles move closer.'),
      M('La temperatura de un gas está relacionada con…|La temperatura d’un gas està relacionada amb…|A gas’s temperature is related to…', 'la velocidad media de sus partículas|la velocitat mitjana de les seues partícules|the average speed of its particles', ['su color|el seu color|its colour', 'su masa total|la seua massa total|its total mass'], 'Más rápido, más temperatura.|Més ràpid, més temperatura.|Faster means hotter.'),
      Nq('¿Cuántos kelvin son 27 °C?|Quants kelvin són 27 °C?|How many kelvin is 27 °C?', 300, [246, 27, 2700], 'K = °C + 273.|K = °C + 273.|K = °C + 273.'),
    ]),
  '3E-FQ-5': G(['Boyle (T constante): p₁ · V₁ = p₂ · V₂. Charles (p constante): V₁/T₁ = V₂/T₂. Gay-Lussac (V constante): p₁/T₁ = p₂/T₂. La temperatura, siempre en kelvin.|Boyle (T constant): p₁ · V₁ = p₂ · V₂. Charles (p constant): V₁/T₁ = V₂/T₂. Gay-Lussac (V constant): p₁/T₁ = p₂/T₂. La temperatura, sempre en kelvin.|Boyle (constant T): p₁ × V₁ = p₂ × V₂. Charles (constant p): V₁/T₁ = V₂/T₂. Gay-Lussac (constant V): p₁/T₁ = p₂/T₂. Always use kelvin.'],
    '6 L a 1 atm. Comprimo a 3 atm (misma T). ¿Volumen?|6 L a 1 atm. Comprimisc a 3 atm (mateixa T). Volum?|6 L at 1 atm. Compressed to 3 atm (same T). Volume?', ['1 · 6 = 3 · V₂.|1 · 6 = 3 · V₂.|1 × 6 = 3 × V₂.', 'V₂ = 2 L.|V₂ = 2 L.|V₂ = 2 L.'], gasLaws()),
  '3E-FQ-6': lesson(['Condensar es pasar de gas a líquido enfriando. Licuar un gas es pasarlo a líquido aumentando la presión (y a menudo enfriando). Así se guarda el butano en las bombonas o el CO₂ en extintores.|Condensar és passar de gas a líquid refredant. Liquar un gas és passar-lo a líquid augmentant la pressió (i sovint refredant). Així es guarda el butà en les bombones o el CO₂ en extintors.|Condensing turns a gas into a liquid by cooling. Liquefying a gas turns it into a liquid by raising the pressure (often while cooling too). That is how butane is stored in gas bottles and CO₂ in extinguishers.'],
    '¿Por qué el butano de la bombona es líquido?|Per què el butà de la bombona és líquid?|Why is the butane in a gas bottle liquid?', ['Está a mucha presión.|Està a molta pressió.|It is under high pressure.', 'Al abrir, baja la presión y sale como gas.|En obrir, baixa la pressió i ix com a gas.|When opened, the pressure drops and it comes out as gas.'], [
      M('Pasar un gas a líquido aumentando la presión se llama…|Passar un gas a líquid augmentant la pressió es diu…|Turning a gas into a liquid by raising the pressure is called…', 'licuefacción|liqüefacció|liquefaction', ['sublimación|sublimació|sublimation', 'fusión|fusió|melting'], 'Licuar = hacer líquido.|Liquar = fer líquid.|Liquefy = make liquid.'),
      M('Las gotas en el exterior de un vaso frío son…|Les gotes en l’exterior d’un got fred són…|Drops on the outside of a cold glass are…', 'vapor del aire condensado|vapor de l’aire condensat|water vapour from the air that has condensed', ['agua que atraviesa el vaso|aigua que travessa el got|water passing through the glass', 'hielo fundido|gel fos|melted ice'], 'El vapor se enfría al tocar el vaso.|El vapor es refreda en tocar el got.|The vapour cools on the glass.'),
      TF('Las nubes se forman cuando el vapor de agua se condensa en altura.|Els núvols es formen quan el vapor d’aigua es condensa en altura.|Clouds form when water vapour condenses high up.', true, 'Allí hace más frío.|Allà fa més fred.|It is colder up there.'),
      M('El rocío de la mañana es…|La rosada del matí és…|Morning dew is…', 'condensación|condensació|condensation', ['evaporación|evaporació|evaporation', 'fusión|fusió|melting'], 'De noche el aire se enfría.|De nit l’aire es refreda.|The air cools at night.'),
      TF('Al condensarse, un gas libera energía.|En condensar-se, un gas allibera energia.|A gas gives out energy when it condenses.', true, 'Lo contrario que la evaporación, que absorbe energía.|El contrari que l’evaporació, que absorbix energia.|The opposite of evaporation, which takes in energy.'),
      M('En un frigorífico, el gas refrigerante…|En un frigorífic, el gas refrigerant…|In a fridge, the refrigerant gas…', 'se comprime, se licúa y luego se evapora absorbiendo calor|es comprimix, es liqua i després s’evapora absorbint calor|is compressed, liquefied and then evaporates, absorbing heat', ['se quema|es crema|burns', 'se convierte en hielo|es convertix en gel|turns into ice'], 'Evaporarse absorbe calor del interior.|Evaporar-se absorbix calor de l’interior.|Evaporating takes heat from inside.'),
    ]),
  '3E-FQ-7': lesson(['La atmósfera es la capa de gases que rodea la Tierra: 78 % nitrógeno, 21 % oxígeno, y pequeñas cantidades de argón, CO₂ y vapor de agua. Protege de radiaciones (capa de ozono), regula la temperatura (efecto invernadero natural) y permite la vida.|L’atmosfera és la capa de gasos que envolta la Terra: 78 % nitrogen, 21 % oxigen, i xicotetes quantitats d’argó, CO₂ i vapor d’aigua. Protegix de radiacions (capa d’ozó), regula la temperatura (efecte d’hivernacle natural) i permet la vida.|The atmosphere is the layer of gases around the Earth: 78% nitrogen, 21% oxygen, plus small amounts of argon, CO₂ and water vapour. It shields us from radiation (ozone layer), regulates temperature (natural greenhouse effect) and makes life possible.'],
    '¿Cuál es el gas más abundante del aire?|Quin és el gas més abundant de l’aire?|What is the most abundant gas in air?', ['Ocupa casi 4/5 del aire.|Ocupa quasi 4/5 de l’aire.|It makes up nearly 4/5 of the air.', 'El nitrógeno (78 %).|El nitrogen (78 %).|Nitrogen (78%).'], [
      M('¿Qué capa nos protege de la radiación ultravioleta?|Quina capa ens protegix de la radiació ultraviolada?|Which layer protects us from ultraviolet radiation?', 'la capa de ozono|la capa d’ozó|the ozone layer', ['la troposfera|la troposfera|the troposphere', 'la corteza|l’escorça|the crust'], 'Está en la estratosfera.|Està en l’estratosfera.|It is in the stratosphere.'),
      Nq('¿Qué porcentaje del aire es oxígeno (aprox.)?|Quin percentatge de l’aire és oxigen (aprox.)?|About what percentage of air is oxygen?', 21, [78, 1, 50], 'Algo más de una quinta parte.|Una mica més d’una cinquena part.|A little over a fifth.'),
      M('El aumento de CO₂ en la atmósfera intensifica…|L’augment de CO₂ en l’atmosfera intensifica…|More CO₂ in the atmosphere strengthens…', 'el efecto invernadero|l’efecte d’hivernacle|the greenhouse effect', ['la capa de ozono|la capa d’ozó|the ozone layer', 'la gravedad|la gravetat|gravity'], 'Retiene más calor.|Reté més calor.|It traps more heat.'),
      TF('Sin efecto invernadero natural, la Tierra sería mucho más fría.|Sense efecte d’hivernacle natural, la Terra seria molt més freda.|Without the natural greenhouse effect, the Earth would be much colder.', true, 'Unos −18 °C de media.|Uns −18 °C de mitjana.|About −18 °C on average.'),
      M('Los fenómenos meteorológicos ocurren en la…|Els fenòmens meteorològics ocorren en la…|Weather happens in the…', 'troposfera|troposfera|troposphere', ['estratosfera|estratosfera|stratosphere', 'termosfera|termosfera|thermosphere'], 'Es la capa más baja.|És la capa més baixa.|It is the lowest layer.'),
      M('¿Qué contaminante se forma al quemar combustibles con poco oxígeno?|Quin contaminant es forma en cremar combustibles amb poc oxigen?|Which pollutant forms when fuels burn with little oxygen?', 'monóxido de carbono (CO)|monòxid de carboni (CO)|carbon monoxide (CO)', ['nitrógeno (N₂)|nitrogen (N₂)|nitrogen (N₂)', 'ozono estratosférico|ozó estratosfèric|stratospheric ozone'], 'Es muy tóxico.|És molt tòxic.|It is very toxic.'),
    ]),
  '3E-FQ-8': lesson(['Teoría atómica de Dalton (1808): la materia está formada por átomos indivisibles; los átomos de un elemento son iguales entre sí; los compuestos se forman uniendo átomos en proporciones de números enteros sencillos; en las reacciones, los átomos se reorganizan.|Teoria atòmica de Dalton (1808): la matèria està formada per àtoms indivisibles; els àtoms d’un element són iguals entre si; els composts es formen unint àtoms en proporcions de nombres enters senzills; en les reaccions, els àtoms es reorganitzen.|Dalton’s atomic theory (1808): matter is made of indivisible atoms; atoms of one element are identical; compounds form by joining atoms in simple whole-number ratios; in reactions, atoms rearrange.', 'Hoy sabemos que el átomo sí se puede dividir (protones, neutrones, electrones).|Hui sabem que l’àtom sí que es pot dividir (protons, neutrons, electrons).|Today we know atoms can be divided (protons, neutrons, electrons).'],
    '¿Qué idea de Dalton se demostró falsa?|Quina idea de Dalton es va demostrar falsa?|Which of Dalton’s ideas turned out false?', ['Se descubrió el electrón en 1897.|Es va descobrir l’electró el 1897.|The electron was discovered in 1897.', 'Que el átomo es indivisible.|Que l’àtom és indivisible.|That the atom is indivisible.'], [
      M('Según Dalton, en una reacción química los átomos…|Segons Dalton, en una reacció química els àtoms…|According to Dalton, in a chemical reaction atoms…', 'se reorganizan|es reorganitzen|rearrange', ['se destruyen|es destruïxen|are destroyed', 'se crean|es creen|are created'], 'Por eso se conserva la masa.|Per això es conserva la massa.|That is why mass is conserved.'),
      TF('Dalton pensaba que todos los átomos de un mismo elemento son iguales.|Dalton pensava que tots els àtoms d’un mateix element són iguals.|Dalton thought all atoms of one element are identical.', true, 'Hoy sabemos que existen isótopos.|Hui sabem que hi ha isòtops.|Today we know isotopes exist.'),
      M('El agua tiene siempre 2 átomos de H por cada 1 de O. Esto apoya la idea de…|L’aigua té sempre 2 àtoms d’H per cada 1 d’O. Açò dona suport a la idea de…|Water always has 2 H atoms for each O. This supports the idea of…', 'proporciones de números enteros|proporcions de nombres enters|whole-number ratios', ['átomos divisibles|àtoms divisibles|divisible atoms', 'electrones en órbitas|electrons en òrbites|electrons in orbits'], 'Ley de las proporciones definidas.|Llei de les proporcions definides.|Law of definite proportions.'),
      M('Dalton representaba los átomos como…|Dalton representava els àtoms com…|Dalton pictured atoms as…', 'esferas macizas|esferes massisses|solid spheres', ['nubes de electrones|núvols d’electrons|electron clouds', 'pasteles con pasas|pastissos amb panses|plum puddings'], 'Sin partes internas.|Sense parts internes.|With no internal parts.'),
      TF('Un modelo científico puede cambiar cuando aparecen nuevas pruebas.|Un model científic pot canviar quan apareixen proves noves.|A scientific model can change when new evidence appears.', true, 'Así ha ido mejorando el modelo atómico.|Així ha anat millorant el model atòmic.|That is how the atomic model has improved.'),
      M('¿Qué partícula del átomo descubrió Thomson?|Quina partícula de l’àtom va descobrir Thomson?|Which particle did Thomson discover?', 'el electrón|l’electró|the electron', ['el neutrón|el neutró|the neutron', 'el núcleo|el nucli|the nucleus'], 'En 1897, con rayos catódicos.|El 1897, amb raigs catòdics.|In 1897, using cathode rays.'),
    ]),
  '3E-FQ-9': G(['Una reacción química es un reordenamiento de átomos: se rompen enlaces de los reactivos y se forman otros nuevos en los productos. Se representa con una ecuación química.|Una reacció química és una reordenació d’àtoms: es trenquen enllaços dels reactius i se’n formen de nous en els productes. Es representa amb una equació química.|A chemical reaction is a rearrangement of atoms: bonds in the reactants break and new ones form in the products. It is written as a chemical equation.'],
    'C + O₂ → CO₂. ¿Reactivos y productos?|C + O₂ → CO₂. Reactius i productes?|C + O₂ → CO₂. Reactants and products?', ['Reactivos: carbono y oxígeno.|Reactius: carboni i oxigen.|Reactants: carbon and oxygen.', 'Producto: dióxido de carbono.|Producte: diòxid de carboni.|Product: carbon dioxide.'], massConservation(), [
      M('En una ecuación química, la flecha significa…|En una equació química, la fletxa significa…|In a chemical equation, the arrow means…', '«se transforma en»|«es transforma en»|"turns into"', ['«es igual a»|«és igual a»|"is equal to"', '«se suma con»|«se suma amb»|"is added to"'], 'Reactivos → productos.|Reactius → productes.|Reactants → products.'),
    ]),
  '3E-FQ-10': G(['Ley de Lavoisier: la masa se conserva en las reacciones. Ley de Proust: los elementos de un compuesto se combinan siempre en la misma proporción en masa (en el agua, 1 g de H por cada 8 g de O).|Llei de Lavoisier: la massa es conserva en les reaccions. Llei de Proust: els elements d’un compost es combinen sempre en la mateixa proporció en massa (en l’aigua, 1 g d’H per cada 8 g d’O).|Lavoisier’s law: mass is conserved in reactions. Proust’s law: the elements in a compound always combine in the same mass ratio (in water, 1 g of H for every 8 g of O).'],
    '¿Cuánto oxígeno reacciona con 3 g de hidrógeno para formar agua?|Quant oxigen reacciona amb 3 g d’hidrogen per a formar aigua?|How much oxygen reacts with 3 g of hydrogen to make water?', ['Proporción 1 : 8.|Proporció 1 : 8.|Ratio 1 : 8.', '3 · 8 = 24 g de O; agua: 27 g.|3 · 8 = 24 g d’O; aigua: 27 g.|3 × 8 = 24 g of O; water: 27 g.'], mix(massConservation(), (r) => { const h = 1 + Math.floor(r() * 9);
      return Nq(`En el agua, el hidrógeno y el oxígeno se combinan en proporción 1 : 8 en masa. ¿Cuántos gramos de oxígeno reaccionan con ${h} g de hidrógeno?|En l’aigua, l’hidrogen i l’oxigen es combinen en proporció 1 : 8 en massa. Quants grams d’oxigen reaccionen amb ${h} g d’hidrogen?|In water, hydrogen and oxygen combine in a 1 : 8 mass ratio. How many grams of oxygen react with ${h} g of hydrogen?`, 8 * h, [h + 8, 9 * h, h / 8].map((x) => Math.round(x * 100) / 100), 'Multiplica por 8.|Multiplica per 8.|Multiply by 8.'); })),
  '3E-FQ-11': lesson(['Una ecuación química ajustada tiene el mismo número de átomos de cada elemento a ambos lados. Se ajusta con coeficientes delante de las fórmulas, nunca cambiando los subíndices.|Una equació química ajustada té el mateix nombre d’àtoms de cada element a tots dos costats. S’ajusta amb coeficients davant de les fórmules, mai canviant els subíndexs.|A balanced chemical equation has the same number of each kind of atom on both sides. Balance it with numbers in front of formulas, never by changing subscripts.'],
    'Ajusta: H₂ + O₂ → H₂O|Ajusta: H₂ + O₂ → H₂O|Balance: H₂ + O₂ → H₂O', ['A la izquierda hay 2 O; pongo 2 H₂O.|A l’esquerra hi ha 2 O; pose 2 H₂O.|There are 2 O on the left; write 2 H₂O.', 'Ahora hay 4 H: 2 H₂ + O₂ → 2 H₂O.|Ara hi ha 4 H: 2 H₂ + O₂ → 2 H₂O.|Now there are 4 H: 2 H₂ + O₂ → 2 H₂O.'], [
      Nq('N₂ + 3 H₂ → ? NH₃. ¿Coeficiente del NH₃?|N₂ + 3 H₂ → ? NH₃. Coeficient del NH₃?|N₂ + 3 H₂ → ? NH₃. Coefficient of NH₃?', 2, [1, 3, 6], 'Hay 2 N a la izquierda.|Hi ha 2 N a l’esquerra.|There are 2 N on the left.'),
      Nq('CH₄ + ? O₂ → CO₂ + 2 H₂O. ¿Coeficiente del O₂?|CH₄ + ? O₂ → CO₂ + 2 H₂O. Coeficient de l’O₂?|CH₄ + ? O₂ → CO₂ + 2 H₂O. Coefficient of O₂?', 2, [1, 3, 4], 'A la derecha hay 2 + 2 = 4 O.|A la dreta hi ha 2 + 2 = 4 O.|There are 2 + 2 = 4 O on the right.'),
      Nq('? Fe + 3 O₂ → 2 Fe₂O₃. ¿Coeficiente del Fe?|? Fe + 3 O₂ → 2 Fe₂O₃. Coeficient del Fe?|? Fe + 3 O₂ → 2 Fe₂O₃. Coefficient of Fe?', 4, [2, 3, 6], '2 Fe₂O₃ tienen 4 Fe.|2 Fe₂O₃ tenen 4 Fe.|2 Fe₂O₃ contain 4 Fe.'),
      TF('Para ajustar, se puede cambiar H₂O por H₂O₂.|Per a ajustar, es pot canviar H₂O per H₂O₂.|To balance, you can change H₂O to H₂O₂.', false, 'Eso sería otra sustancia (agua oxigenada).|Això seria una altra substància (aigua oxigenada).|That would be a different substance (hydrogen peroxide).'),
      M('¿Qué ecuación está ajustada?|Quina equació està ajustada?|Which equation is balanced?', '2 Na + Cl₂ → 2 NaCl|2 Na + Cl₂ → 2 NaCl|2 Na + Cl₂ → 2 NaCl', ['Na + Cl₂ → NaCl|Na + Cl₂ → NaCl|Na + Cl₂ → NaCl', '2 Na + Cl₂ → NaCl|2 Na + Cl₂ → NaCl|2 Na + Cl₂ → NaCl'], 'Cuenta Na y Cl a cada lado.|Compta Na i Cl a cada costat.|Count Na and Cl on each side.'),
      Nq('CaCO₃ → CaO + CO₂. ¿Cuántos átomos de O hay a la derecha?|CaCO₃ → CaO + CO₂. Quants àtoms d’O hi ha a la dreta?|CaCO₃ → CaO + CO₂. How many O atoms are on the right?', 3, [2, 1, 4], '1 en CaO y 2 en CO₂.|1 en CaO i 2 en CO₂.|1 in CaO and 2 in CO₂.'),
    ]),
  '3E-FQ-12': lesson(['El hidrógeno puede ser un vector energético: al reaccionar con oxígeno (en una pila de combustible) produce electricidad y solo agua. Es «verde» si se obtiene por electrólisis del agua con energía renovable. Retos: almacenarlo y transportarlo.|L’hidrogen pot ser un vector energètic: en reaccionar amb oxigen (en una pila de combustible) produïx electricitat i només aigua. És «verd» si s’obté per electròlisi de l’aigua amb energia renovable. Reptes: emmagatzemar-lo i transportar-lo.|Hydrogen can carry energy: reacting with oxygen (in a fuel cell) it produces electricity and only water. It is "green" if made by electrolysis of water using renewable energy. Challenges: storing and transporting it.'],
    '¿Qué emite un coche de hidrógeno por el tubo de escape?|Què emet un cotxe d’hidrogen pel tub d’escapament?|What comes out of a hydrogen car’s exhaust?', ['2 H₂ + O₂ → 2 H₂O.|2 H₂ + O₂ → 2 H₂O.|2 H₂ + O₂ → 2 H₂O.', 'Solo vapor de agua.|Només vapor d’aigua.|Only water vapour.'], [
      M('El hidrógeno «verde» se obtiene…|L’hidrogen «verd» s’obté…|"Green" hydrogen is made…', 'por electrólisis con electricidad renovable|per electròlisi amb electricitat renovable|by electrolysis using renewable electricity', ['del petróleo|del petroli|from crude oil', 'del carbón|del carbó|from coal'], 'No emite CO₂ al producirse.|No emet CO₂ en produir-se.|No CO₂ is released making it.'),
      M('Una pila de combustible transforma energía química en…|Una pila de combustible transforma energia química en…|A fuel cell turns chemical energy into…', 'energía eléctrica|energia elèctrica|electrical energy', ['energía nuclear|energia nuclear|nuclear energy', 'masa|massa|mass'], 'Como una pila que no se agota mientras le llegue hidrógeno.|Com una pila que no s’esgota mentre li arribe hidrogen.|Like a battery that keeps going as long as it gets hydrogen.'),
      TF('El hidrógeno es una fuente de energía primaria que encontramos libre en la naturaleza.|L’hidrogen és una font d’energia primària que trobem lliure en la natura.|Hydrogen is a primary energy source found free in nature.', false, 'Hay que producirlo: es un vector, no una fuente.|Cal produir-lo: és un vector, no una font.|It must be produced: it is a carrier, not a source.'),
      M('Un problema del hidrógeno es que…|Un problema de l’hidrogen és que…|One problem with hydrogen is that…', 'es difícil de almacenar|és difícil d’emmagatzemar|it is hard to store', ['contamina mucho al usarlo|contamina molt en usar-lo|it pollutes a lot when used', 'es muy pesado|és molt pesant|it is very heavy'], 'Hay que comprimirlo mucho o enfriarlo.|Cal comprimir-lo molt o refredar-lo.|It must be highly compressed or cooled.'),
      TF('El hidrógeno es muy inflamable.|L’hidrogen és molt inflamable.|Hydrogen is very flammable.', true, 'Hay que manejarlo con seguridad.|Cal manejar-lo amb seguretat.|It must be handled safely.'),
      M('Producto de la combustión del hidrógeno:|Producte de la combustió de l’hidrogen:|Product of burning hydrogen:', 'agua|aigua|water', ['CO₂|CO₂|CO₂', 'humo negro|fum negre|black smoke'], 'No tiene carbono.|No té carboni.|It contains no carbon.'),
    ]),
  '3E-FQ-13': lesson(['La energía es la capacidad de producir cambios. Se mide en julios (J). Formas: cinética, potencial, térmica, química, eléctrica, nuclear, luminosa. No se crea ni se destruye: se transforma (y parte se degrada en calor).|L’energia és la capacitat de produir canvis. Es mesura en joules (J). Formes: cinètica, potencial, tèrmica, química, elèctrica, nuclear, lluminosa. No es crea ni es destruïx: es transforma (i part es degrada en calor).|Energy is the ability to cause change. It is measured in joules (J). Forms: kinetic, potential, thermal, chemical, electrical, nuclear, light. It is neither created nor destroyed: it is transformed (and some is wasted as heat).'],
    '¿Qué transformación hace una bombilla?|Quina transformació fa una bombeta?|What transformation does a light bulb carry out?', ['Recibe energía eléctrica.|Rep energia elèctrica.|It takes in electrical energy.', 'Da luz (y algo de calor).|Dona llum (i una mica de calor).|It gives light (and some heat).'], [
      M('Una pila transforma energía…|Una pila transforma energia…|A battery transforms energy from…', 'química en eléctrica|química en elèctrica|chemical to electrical', ['eléctrica en química|elèctrica en química|electrical to chemical', 'nuclear en luminosa|nuclear en lluminosa|nuclear to light'], 'Las reacciones químicas mueven electrones.|Les reaccions químiques mouen electrons.|Chemical reactions push electrons.'),
      M('Un objeto en lo alto de una estantería tiene energía…|Un objecte dalt d’una prestatgeria té energia…|An object on a high shelf has…', 'potencial gravitatoria|potencial gravitatòria|gravitational potential energy', ['cinética|cinètica|kinetic energy', 'nuclear|nuclear|nuclear energy'], 'Depende de la altura.|Depén de l’altura.|It depends on height.'),
      M('Un aerogenerador transforma energía…|Un aerogenerador transforma energia…|A wind turbine transforms energy from…', 'cinética del viento en eléctrica|cinètica del vent en elèctrica|the wind’s kinetic energy to electrical', ['química en térmica|química en tèrmica|chemical to thermal', 'eléctrica en cinética|elèctrica en cinètica|electrical to kinetic'], 'El viento mueve las palas.|El vent mou les pales.|The wind turns the blades.'),
      TF('En toda transformación, parte de la energía se degrada en calor.|En tota transformació, part de l’energia es degrada en calor.|In every transformation, some energy is wasted as heat.', true, 'Por eso ninguna máquina rinde al 100 %.|Per això cap màquina rendix al 100 %.|That is why no machine is 100% efficient.'),
      M('Los alimentos contienen energía…|Els aliments contenen energia…|Food contains…', 'química|química|chemical energy', ['eléctrica|elèctrica|electrical energy', 'nuclear|nuclear|nuclear energy'], 'Se libera en la respiración celular.|S’allibera en la respiració cel·lular.|It is released in cellular respiration.'),
      M('La unidad de energía en el SI es…|La unitat d’energia en el SI és…|The SI unit of energy is…', 'el julio (J)|el joule (J)|the joule (J)', ['el vatio (W)|el watt (W)|the watt (W)', 'el newton (N)|el newton (N)|the newton (N)'], 'El vatio mide potencia.|El watt mesura potència.|The watt measures power.'),
    ]),
  '3E-FQ-14': lesson(['La corriente eléctrica es un flujo de electrones por un conductor. Un circuito necesita generador (pila), conductores (cables), receptores (bombilla, motor) y elementos de control (interruptor). Magnitudes: intensidad (A), voltaje (V), resistencia (Ω).|El corrent elèctric és un flux d’electrons per un conductor. Un circuit necessita generador (pila), conductors (cables), receptors (bombeta, motor) i elements de control (interruptor). Magnituds: intensitat (A), voltatge (V), resistència (Ω).|Electric current is a flow of electrons through a conductor. A circuit needs a supply (battery), conductors (wires), components (bulb, motor) and switches. Quantities: current (A), voltage (V), resistance (Ω).'],
    '¿Por qué no se enciende la bombilla con el interruptor abierto?|Per què no s’encén la bombeta amb l’interruptor obert?|Why does the bulb stay off with the switch open?', ['El circuito está cortado.|El circuit està tallat.|The circuit is broken.', 'Los electrones no pueden circular.|Els electrons no poden circular.|Electrons cannot flow.'], [
      M('¿Qué material es buen conductor?|Quin material és bon conductor?|Which material is a good conductor?', 'cobre|coure|copper', ['plástico|plàstic|plastic', 'madera|fusta|wood'], 'Los metales conducen bien.|Els metalls condueixen bé.|Metals conduct well.'),
      M('La intensidad de corriente se mide en…|La intensitat de corrent es mesura en…|Current is measured in…', 'amperios (A)|amperes (A)|amperes (A)', ['voltios (V)|volts (V)|volts (V)', 'ohmios (Ω)|ohms (Ω)|ohms (Ω)'], 'Con un amperímetro en serie.|Amb un amperímetre en sèrie.|With an ammeter in series.'),
      M('El voltaje se mide con…|El voltatge es mesura amb…|Voltage is measured with…', 'un voltímetro en paralelo|un voltímetre en paral·lel|a voltmeter in parallel', ['un amperímetro en serie|un amperímetre en sèrie|an ammeter in series', 'una balanza|una balança|a balance'], 'Se conecta a los extremos del elemento.|Es connecta als extrems de l’element.|It connects across the component.'),
      TF('En un circuito en paralelo, si se funde una bombilla, las demás siguen encendidas.|En un circuit en paral·lel, si es fon una bombeta, les altres continuen enceses.|In a parallel circuit, if one bulb blows, the others stay on.', true, 'Cada una tiene su propio camino.|Cada una té el seu propi camí.|Each has its own path.'),
      M('El plástico de los cables sirve como…|El plàstic dels cables servix com a…|The plastic on wires acts as…', 'aislante|aïllant|an insulator', ['conductor|conductor|a conductor', 'generador|generador|a power supply'], 'Evita descargas.|Evita descàrregues.|It prevents shocks.'),
      TF('En un circuito en serie, si se funde una bombilla, se apagan todas.|En un circuit en sèrie, si es fon una bombeta, s’apaguen totes.|In a series circuit, if one bulb blows, they all go out.', true, 'Solo hay un camino.|Només hi ha un camí.|There is only one path.'),
    ]),
  '3E-FQ-15': G(['Ley de Ohm: V = I · R. La intensidad que pasa por un conductor es proporcional al voltaje e inversamente proporcional a su resistencia.|Llei d’Ohm: V = I · R. La intensitat que passa per un conductor és proporcional al voltatge i inversament proporcional a la seua resistència.|Ohm’s law: V = I × R. The current through a conductor is proportional to the voltage and inversely proportional to its resistance.', 'Resistencias en serie se suman; en paralelo, la total es menor que la más pequeña.|Resistències en sèrie se sumen; en paral·lel, la total és menor que la més xicoteta.|Resistors in series add; in parallel, the total is less than the smallest.'],
    'Pila de 9 V y resistencia de 30 Ω. ¿Intensidad?|Pila de 9 V i resistència de 30 Ω. Intensitat?|9 V battery and 30 Ω resistor. Current?', ['I = V / R = 9 / 30.|I = V / R = 9 / 30.|I = V ÷ R = 9 ÷ 30.', '0,3 A.|0,3 A.|0.3 A.'], mix(ohm(), seriesParallel())),
  '3E-FQ-16': G(['Potencia eléctrica: P = V · I (vatios, W). Energía consumida: E = P · t; en casa se mide en kilovatios hora (kWh). El coste es kWh × precio del kWh.|Potència elèctrica: P = V · I (watts, W). Energia consumida: E = P · t; a casa es mesura en quilowatts hora (kWh). El cost és kWh × preu del kWh.|Electrical power: P = V × I (watts, W). Energy used: E = P × t; at home it is measured in kilowatt-hours (kWh). Cost = kWh × price per kWh.'],
    'Un horno de 2 000 W funciona 1,5 h. ¿kWh?|Un forn de 2 000 W funciona 1,5 h. kWh?|A 2,000 W oven runs for 1.5 h. kWh?', ['2 000 W = 2 kW.|2 000 W = 2 kW.|2,000 W = 2 kW.', '2 · 1,5 = 3 kWh.|2 · 1,5 = 3 kWh.|2 × 1.5 = 3 kWh.'], electricPower()),
  '3E-FQ-17': lesson(['La electricidad se produce sobre todo con generadores: un imán que gira dentro de una bobina (o al revés) induce corriente. Lo que hace girar la turbina puede ser vapor (térmicas, nucleares), agua (hidráulicas) o viento. Las placas solares producen electricidad directamente con la luz.|L’electricitat es produïx sobretot amb generadors: un imant que gira dins d’una bobina (o al revés) induïx corrent. El que fa girar la turbina pot ser vapor (tèrmiques, nuclears), aigua (hidràuliques) o vent. Les plaques solars produïxen electricitat directament amb la llum.|Electricity is mostly produced by generators: a magnet spinning inside a coil (or vice versa) induces a current. The turbine may be turned by steam (thermal and nuclear plants), water (hydroelectric) or wind. Solar panels make electricity directly from light.'],
    '¿Qué tienen en común una central térmica y una nuclear?|Què tenen en comú una central tèrmica i una nuclear?|What do a fossil-fuel and a nuclear power station have in common?', ['Ambas calientan agua y hacen vapor.|Totes dues escalfen aigua i fan vapor.|Both heat water to make steam.', 'El vapor mueve una turbina unida a un generador.|El vapor mou una turbina unida a un generador.|The steam turns a turbine linked to a generator.'], [
      M('¿Qué fuente es renovable?|Quina font és renovable?|Which source is renewable?', 'solar|solar|solar', ['carbón|carbó|coal', 'gas natural|gas natural|natural gas'], 'No se agota a escala humana.|No s’esgota a escala humana.|It does not run out on a human timescale.'),
      M('Una central hidroeléctrica aprovecha…|Una central hidroelèctrica aprofita…|A hydroelectric plant uses…', 'la energía potencial del agua embalsada|l’energia potencial de l’aigua embassada|the potential energy of stored water', ['el calor del sol|la calor del sol|the sun’s heat', 'el uranio|l’urani|uranium'], 'El agua cae y mueve la turbina.|L’aigua cau i mou la turbina.|Water falls and turns the turbine.'),
      M('Las placas fotovoltaicas transforman…|Les plaques fotovoltaiques transformen…|Photovoltaic panels convert…', 'luz en electricidad|llum en electricitat|light into electricity', ['calor en movimiento|calor en moviment|heat into motion', 'viento en luz|vent en llum|wind into light'], 'Efecto fotoeléctrico.|Efecte fotoelèctric.|The photovoltaic effect.'),
      TF('Una dinamo de bicicleta es un pequeño generador.|Una dinamo de bicicleta és un xicotet generador.|A bicycle dynamo is a small generator.', true, 'La rueda hace girar un imán.|La roda fa girar un imant.|The wheel spins a magnet.'),
      M('Un inconveniente de la energía nuclear es…|Un inconvenient de l’energia nuclear és…|A drawback of nuclear power is…', 'los residuos radiactivos|els residus radioactius|radioactive waste', ['que emite mucho CO₂|que emet molt de CO₂|high CO₂ emissions', 'que depende del viento|que depén del vent|depending on the wind'], 'Duran miles de años.|Duren milers d’anys.|They last thousands of years.'),
      M('La corriente que llega a los enchufes de casa es…|El corrent que arriba als endolls de casa és…|The current at home sockets is…', 'alterna, a 230 V|alterna, a 230 V|alternating, at 230 V', ['continua, a 9 V|contínua, a 9 V|direct, at 9 V', 'continua, a 1,5 V|contínua, a 1,5 V|direct, at 1.5 V'], 'Las pilas dan corriente continua.|Les piles donen corrent continu.|Batteries give direct current.'),
    ]),
  '3E-FQ-18': G(['El calor es energía que pasa de un cuerpo caliente a uno frío. La temperatura mide la agitación de las partículas. Calor necesario para calentar: Q = m · c · ΔT (c: calor específico; agua: 4 180 J/kg·°C).|La calor és energia que passa d’un cos calent a un de fred. La temperatura mesura l’agitació de les partícules. Calor necessària per a escalfar: Q = m · c · ΔT (c: calor específica; aigua: 4 180 J/kg·°C).|Heat is energy passing from a hot object to a cold one. Temperature measures how fast the particles move. Heat needed to warm something: Q = m × c × ΔT (c: specific heat capacity; water: 4,180 J/kg·°C).'],
    '2 kg de agua de 20 °C a 70 °C. ¿Calor?|2 kg d’aigua de 20 °C a 70 °C. Calor?|2 kg of water from 20 °C to 70 °C. Heat?', ['ΔT = 50 °C.|ΔT = 50 °C.|ΔT = 50 °C.', 'Q = 2 · 4 180 · 50 = 418 000 J.|Q = 2 · 4 180 · 50 = 418 000 J.|Q = 2 × 4,180 × 50 = 418,000 J.'], heat(), [
      TF('Calor y temperatura son lo mismo.|Calor i temperatura són el mateix.|Heat and temperature are the same thing.', false, 'El calor es energía que se transfiere; la temperatura mide la agitación.|La calor és energia que es transferix; la temperatura mesura l’agitació.|Heat is energy transferred; temperature measures particle motion.'),
    ]),
  '3E-FQ-19': lesson(['El calor se transmite por conducción (en sólidos, por contacto), convección (en líquidos y gases, el fluido caliente sube) y radiación (ondas, incluso en el vacío). Los aislantes térmicos (lana, aire, corcho) frenan la conducción.|La calor es transmet per conducció (en sòlids, per contacte), convecció (en líquids i gasos, el fluid calent puja) i radiació (ones, fins i tot en el buit). Els aïllants tèrmics (llana, aire, suro) frenen la conducció.|Heat travels by conduction (in solids, by contact), convection (in liquids and gases, hot fluid rises) and radiation (waves, even through a vacuum). Thermal insulators (wool, air, cork) slow conduction.'],
    '¿Cómo nos llega el calor del Sol?|Com ens arriba la calor del Sol?|How does the Sun’s heat reach us?', ['Entre el Sol y la Tierra hay vacío.|Entre el Sol i la Terra hi ha buit.|There is a vacuum between the Sun and Earth.', 'Por radiación.|Per radiació.|By radiation.'], [
      M('Una cuchara metálica en la sopa se calienta por…|Una cullera metàl·lica en la sopa s’escalfa per…|A metal spoon in hot soup heats up by…', 'conducción|conducció|conduction', ['convección|convecció|convection', 'radiación|radiació|radiation'], 'El calor pasa por el sólido.|La calor passa pel sòlid.|Heat moves through the solid.'),
      M('El aire caliente de un radiador sube y calienta la habitación por…|L’aire calent d’un radiador puja i escalfa l’habitació per…|Warm air rising from a radiator heats the room by…', 'convección|convecció|convection', ['conducción|conducció|conduction', 'radiación|radiació|radiation'], 'Corrientes en el fluido.|Corrents en el fluid.|Currents in the fluid.'),
      M('¿Cuál es mejor aislante térmico?|Quin és millor aïllant tèrmic?|Which is the better thermal insulator?', 'corcho|suro|cork', ['aluminio|alumini|aluminium', 'cobre|coure|copper'], 'Los metales conducen bien el calor.|Els metalls condueixen bé la calor.|Metals conduct heat well.'),
      TF('Un termo funciona porque tiene vacío entre dos paredes.|Un termo funciona perquè té buit entre dues parets.|A vacuum flask works because there is a vacuum between two walls.', true, 'Sin partículas no hay conducción ni convección.|Sense partícules no hi ha conducció ni convecció.|No particles, no conduction or convection.'),
      M('Las paredes con cámara de aire aíslan porque…|Les parets amb cambra d’aire aïllen perquè…|Cavity walls insulate because…', 'el aire quieto conduce mal el calor|l’aire quiet condueix malament la calor|still air is a poor conductor', ['el aire es muy pesado|l’aire és molt pesant|air is very heavy', 'el aire refleja la luz|l’aire reflectix la llum|air reflects light'], 'Por eso abriga la lana.|Per això abriga la llana.|That is why wool keeps you warm.'),
      TF('Las superficies oscuras absorben más radiación que las claras.|Les superfícies fosques absorbixen més radiació que les clares.|Dark surfaces absorb more radiation than light ones.', true, 'Por eso en verano se pintan las casas de blanco.|Per això a l’estiu es pinten les cases de blanc.|That is why houses are painted white in hot places.'),
    ]),
  '3E-FQ-20': G(['El rendimiento de una máquina es la energía útil dividida entre la energía consumida, en %. Siempre es menor del 100 % porque parte se pierde como calor (rozamiento).|El rendiment d’una màquina és l’energia útil dividida entre l’energia consumida, en %. Sempre és menor del 100 % perquè part es perd com a calor (fregament).|A machine’s efficiency is the useful energy divided by the energy supplied, as a %. It is always below 100% because some is lost as heat (friction).'],
    'Un motor consume 500 J y da 400 J útiles. ¿Rendimiento?|Un motor consumix 500 J i dona 400 J útils. Rendiment?|A motor uses 500 J and gives 400 J of useful energy. Efficiency?', ['400 / 500 = 0,8.|400 / 500 = 0,8.|400 ÷ 500 = 0.8.', '80 %.|80 %.|80%.'], efficiency()),
  '3E-FQ-21': lesson(['Usar la energía de forma racional es consumir menos sin perder bienestar: aparatos eficientes (etiqueta A), LED, apagar en lugar de dejar en espera, aislar la casa, transporte público o bici, y fuentes renovables.|Usar l’energia de manera racional és consumir menys sense perdre benestar: aparells eficients (etiqueta A), LED, apagar en compte de deixar en espera, aïllar la casa, transport públic o bici, i fonts renovables.|Using energy wisely means using less without losing comfort: efficient appliances (A rating), LEDs, switching off instead of standby, insulating homes, public transport or cycling, and renewable sources.'],
    'Una bombilla LED de 8 W da la misma luz que una incandescente de 60 W. ¿Cuánto ahorra?|Una bombeta LED de 8 W dona la mateixa llum que una incandescent de 60 W. Quant estalvia?|An 8 W LED gives the same light as a 60 W incandescent bulb. How much does it save?', ['60 − 8 = 52 W.|60 − 8 = 52 W.|60 − 8 = 52 W.', 'Casi un 87 % menos de energía.|Quasi un 87 % menys d’energia.|Nearly 87% less energy.'], [
      M('¿Qué etiqueta energética indica más eficiencia?|Quina etiqueta energètica indica més eficiència?|Which energy label means most efficient?', 'A|A|A', ['D|D|D', 'G|G|G'], 'De A (verde) a G (rojo).|D’A (verd) a G (roig).|From A (green) to G (red).'),
      TF('Dejar aparatos en espera (stand-by) consume energía.|Deixar aparells en espera (stand-by) consumix energia.|Leaving devices on standby uses energy.', true, 'La lucecita gasta todo el día.|El llumet gasta tot el dia.|The little light uses power all day.'),
      M('¿Qué medida ahorra más en calefacción?|Quina mesura estalvia més en calefacció?|Which measure saves most on heating?', 'aislar ventanas y paredes|aïllar finestres i parets|insulating windows and walls', ['abrir ventanas con la calefacción puesta|obrir finestres amb la calefacció posada|opening windows with the heating on', 'subir a 28 °C|pujar a 28 °C|turning it up to 28 °C'], 'Se pierde menos calor.|Es perd menys calor.|Less heat escapes.'),
      Nq('Una nevera A consume 150 kWh/año y una E, 400 kWh/año. A 0,20 €/kWh, ¿cuántos euros ahorra al año la A?|Una nevera A consumix 150 kWh/any i una E, 400 kWh/any. A 0,20 €/kWh, quants euros estalvia a l’any l’A?|An A-rated fridge uses 150 kWh a year and an E-rated one 400 kWh. At €0.20/kWh, how much does the A save per year (€)?', 50, [250, 30, 80], '(400 − 150) · 0,20.|(400 − 150) · 0,20.|(400 − 150) × 0.20.'),
      TF('Ir en bici al instituto ahorra energía y emisiones.|Anar en bici a l’institut estalvia energia i emissions.|Cycling to school saves energy and emissions.', true, 'No quema combustible.|No crema combustible.|It burns no fuel.'),
      M('Ducharse en vez de bañarse ahorra…|Dutxar-se en lloc de banyar-se estalvia…|Showering instead of bathing saves…', 'agua y energía para calentarla|aigua i energia per a escalfar-la|water and the energy to heat it', ['solo jabón|només sabó|only soap', 'nada|res|nothing'], 'Una ducha corta gasta mucha menos agua.|Una dutxa curta gasta molta menys aigua.|A short shower uses far less water.'),
    ]),
  '3E-FQ-22': lesson(['La materia tiene carga eléctrica en protones (+) y electrones (−). Un cuerpo se carga al ganar electrones (negativo) o al perderlos (positivo), por frotamiento, contacto o inducción. La carga se mide en culombios (C).|La matèria té càrrega elèctrica en protons (+) i electrons (−). Un cos es carrega en guanyar electrons (negatiu) o en perdre’ls (positiu), per fregament, contacte o inducció. La càrrega es mesura en coulombs (C).|Matter carries electric charge in protons (+) and electrons (−). An object becomes charged by gaining electrons (negative) or losing them (positive), by friction, contact or induction. Charge is measured in coulombs (C).'],
    'Froto una barra de plástico con lana y queda negativa. ¿Qué ha pasado?|Fregue una barra de plàstic amb llana i queda negativa. Què ha passat?|I rub a plastic rod with wool and it becomes negative. What happened?', ['Los protones no se mueven.|Els protons no es mouen.|Protons do not move.', 'La barra ha ganado electrones de la lana.|La barra ha guanyat electrons de la llana.|The rod gained electrons from the wool.'], [
      M('Un cuerpo con carga positiva ha…|Un cos amb càrrega positiva ha…|A positively charged object has…', 'perdido electrones|perdut electrons|lost electrons', ['ganado protones|guanyat protons|gained protons', 'ganado electrones|guanyat electrons|gained electrons'], 'Solo se mueven los electrones.|Només es mouen els electrons.|Only electrons move.'),
      M('La unidad de carga eléctrica es…|La unitat de càrrega elèctrica és…|The unit of electric charge is…', 'el culombio (C)|el coulomb (C)|the coulomb (C)', ['el amperio (A)|l’ampere (A)|the ampere (A)', 'el voltio (V)|el volt (V)|the volt (V)'], 'En honor a Coulomb.|En honor de Coulomb.|Named after Coulomb.'),
      TF('Al quitarte un jersey de lana a veces saltan chispas por electricidad estática.|En llevar-te un jersei de llana a vegades salten espurnes per electricitat estàtica.|Taking off a wool jumper sometimes makes sparks from static electricity.', true, 'El roce separa cargas.|El frec separa càrregues.|Rubbing separates charges.'),
      M('Un rayo es…|Un llamp és…|Lightning is…', 'una descarga eléctrica entre nubes o nube y suelo|una descàrrega elèctrica entre núvols o núvol i terra|an electric discharge between clouds or cloud and ground', ['fuego del cielo|foc del cel|fire from the sky', 'luz del sol reflejada|llum del sol reflectida|reflected sunlight'], 'Las nubes acumulan mucha carga.|Els núvols acumulen molta càrrega.|Clouds build up a lot of charge.'),
      TF('La carga eléctrica total se conserva.|La càrrega elèctrica total es conserva.|Total electric charge is conserved.', true, 'Lo que uno gana, otro lo pierde.|El que un guanya, un altre ho perd.|What one gains, another loses.'),
      M('El pararrayos sirve para…|El parallamps servix per a…|A lightning conductor is used to…', 'conducir la descarga a tierra sin daños|conduir la descàrrega a terra sense danys|carry the discharge safely to the ground', ['atraer la lluvia|atraure la pluja|attract rain', 'producir electricidad para casa|produir electricitat per a casa|make electricity for the house'], 'Lo inventó Benjamin Franklin.|El va inventar Benjamin Franklin.|Benjamin Franklin invented it.'),
    ]),
  '3E-FQ-23': G(['Ley de Coulomb: F = k · q₁ · q₂ / d². La fuerza entre dos cargas es proporcional al producto de las cargas e inversamente proporcional al cuadrado de la distancia.|Llei de Coulomb: F = k · q₁ · q₂ / d². La força entre dues càrregues és proporcional al producte de les càrregues i inversament proporcional al quadrat de la distància.|Coulomb’s law: F = k × q₁ × q₂ ÷ d². The force between two charges is proportional to the product of the charges and inversely proportional to the square of the distance.'],
    'Si la distancia se reduce a la mitad, ¿qué le pasa a la fuerza?|Si la distància es reduïx a la meitat, què li passa a la força?|If the distance is halved, what happens to the force?', ['d pasa a d/2; d² pasa a d²/4.|d passa a d/2; d² passa a d²/4.|d becomes d/2; d² becomes d²/4.', 'La fuerza se multiplica por 4.|La força es multiplica per 4.|The force is multiplied by 4.'], coulomb()),
  '3E-FQ-24': lesson(['Los imanes tienen polo norte y polo sur. La corriente eléctrica crea un campo magnético (Ørsted) y un imán en movimiento genera corriente (Faraday): es el electromagnetismo. En él se basan motores, generadores, altavoces y transformadores.|Els imants tenen pol nord i pol sud. El corrent elèctric crea un camp magnètic (Ørsted) i un imant en moviment genera corrent (Faraday): és l’electromagnetisme. En ell es basen motors, generadors, altaveus i transformadors.|Magnets have a north and a south pole. Electric current creates a magnetic field (Ørsted) and a moving magnet generates current (Faraday): this is electromagnetism. Motors, generators, loudspeakers and transformers depend on it.'],
    '¿Qué descubrió Ørsted con una brújula y un cable?|Què va descobrir Ørsted amb una brúixola i un cable?|What did Ørsted discover with a compass and a wire?', ['La aguja se movía al pasar corriente.|L’agulla es movia en passar corrent.|The needle moved when current flowed.', 'La corriente crea un campo magnético.|El corrent crea un camp magnètic.|Current creates a magnetic field.'], [
      M('Un motor eléctrico transforma energía…|Un motor elèctric transforma energia…|An electric motor transforms energy from…', 'eléctrica en mecánica|elèctrica en mecànica|electrical to mechanical', ['mecánica en eléctrica|mecànica en elèctrica|mechanical to electrical', 'química en luminosa|química en lluminosa|chemical to light'], 'El generador hace lo contrario.|El generador fa el contrari.|A generator does the opposite.'),
      M('Si partes un imán por la mitad obtienes…|Si partixes un imant per la meitat obtens…|If you cut a magnet in half you get…', 'dos imanes, cada uno con polo N y S|dos imants, cadascun amb pol N i S|two magnets, each with N and S poles', ['un polo norte y un polo sur separados|un pol nord i un pol sud separats|a separate north and south pole', 'trozos sin magnetismo|trossos sense magnetisme|pieces with no magnetism'], 'No existen polos aislados.|No hi ha pols aïllats.|Single poles do not exist.'),
      TF('Al mover un imán dentro de una bobina se produce corriente eléctrica.|En moure un imant dins d’una bobina es produïx corrent elèctric.|Moving a magnet inside a coil produces an electric current.', true, 'Inducción electromagnética (Faraday).|Inducció electromagnètica (Faraday).|Electromagnetic induction (Faraday).'),
      M('El campo magnético terrestre nos protege de…|El camp magnètic terrestre ens protegix de…|The Earth’s magnetic field protects us from…', 'las partículas cargadas del viento solar|les partícules carregades del vent solar|charged particles in the solar wind', ['la lluvia|la pluja|rain', 'los terremotos|els terratrémols|earthquakes'], 'Por eso hay auroras polares.|Per això hi ha aurores polars.|That causes the northern lights.'),
      M('Un transformador sirve para…|Un transformador servix per a…|A transformer is used to…', 'cambiar el voltaje de la corriente alterna|canviar el voltatge del corrent altern|change the voltage of alternating current', ['almacenar electricidad|emmagatzemar electricitat|store electricity', 'producir luz|produir llum|make light'], 'Por ejemplo, de 230 V a 5 V en un cargador.|Per exemple, de 230 V a 5 V en un carregador.|For example, 230 V to 5 V in a charger.'),
      TF('Un electroimán se puede encender y apagar.|Un electroimant es pot encendre i apagar.|An electromagnet can be switched on and off.', true, 'Funciona solo con corriente.|Funciona només amb corrent.|It only works with current.'),
    ]),
};
export default P;
